        origenDispositivo.isAcceptableOrUnknown(
          data['origen_dispositivo']!,
          _origenDispositivoMeta,
        ),
      );
    }
    if (data.containsKey('actualizado_en')) {
      context.handle(
        _actualizadoEnMeta,
        actualizadoEn.isAcceptableOrUnknown(
          data['actualizado_en']!,
          _actualizadoEnMeta,
        ),
      );
    }
    return context;
  }

