  Proveedor copyWith({
    int? id,
    String? codigo,
    String? nombre,
    Value<String?> diaPedido = const Value.absent(),
    Value<String?> diaEntrega = const Value.absent(),
    int? colchonReposicionCentavos,
    String? medioPago,
    Value<DateTime?> corteReposicionFecha = const Value.absent(),
    int? pendienteBaseCentavos,
    int? separadoCentavos,
    int? separadoMpCentavos,
    Value<DateTime?> separadoFecha = const Value.absent(),
    Value<DateTime?> separadoDelDiaFecha = const Value.absent(),
    int? separadoDelDiaCentavos,
    int? separadoDelDiaMpCentavos,
    Value<DateTime?> corteAntesDelDia = const Value.absent(),
    int? pendienteBaseAntesDelDiaCentavos,
    Value<DateTime?> ultimoPagoFecha = const Value.absent(),
    Value<DateTime?> gananciaRevisadaFecha = const Value.absent(),
    Value<int?> markupBp = const Value.absent(),
    Value<String?> whatsapp = const Value.absent(),
    bool? activo,
    bool? cajaAparte,
    Value<String?> globalId = const Value.absent(),
    Value<String?> origenDispositivo = const Value.absent(),
    Value<DateTime?> actualizadoEn = const Value.absent(),
  }) => Proveedor(
    id: id ?? this.id,
    codigo: codigo ?? this.codigo,
    nombre: nombre ?? this.nombre,
    diaPedido: diaPedido.present ? diaPedido.value : this.diaPedido,
    diaEntrega: diaEntrega.present ? diaEntrega.value : this.diaEntrega,
    colchonReposicionCentavos:
        colchonReposicionCentavos ?? this.colchonReposicionCentavos,
    medioPago: medioPago ?? this.medioPago,
    corteReposicionFecha: corteReposicionFecha.present
        ? corteReposicionFecha.value
        : this.corteReposicionFecha,
    pendienteBaseCentavos: pendienteBaseCentavos ?? this.pendienteBaseCentavos,
    separadoCentavos: separadoCentavos ?? this.separadoCentavos,
    separadoMpCentavos: separadoMpCentavos ?? this.separadoMpCentavos,
    separadoFecha: separadoFecha.present
        ? separadoFecha.value
        : this.separadoFecha,
    separadoDelDiaFecha: separadoDelDiaFecha.present
        ? separadoDelDiaFecha.value
        : this.separadoDelDiaFecha,
    separadoDelDiaCentavos:
        separadoDelDiaCentavos ?? this.separadoDelDiaCentavos,
