class Cliente extends DataClass implements Insertable<Cliente> {
  final int id;
  final String nombre;
  final String? telefono;

  /// Basis points, ej. 1500 = 15% (Cliente Frecuente, Regla 17). Null para todos los
  /// clientes que no tienen descuento fijo.
  final int? descuentoBp;
  final String? notas;
  final bool activo;

  /// Identidad de sincronización — ver el comentario de [Categorias.globalId].
  final String? globalId;
  final String? origenDispositivo;
  final DateTime? actualizadoEn;
  const Cliente({
    required this.id,
    required this.nombre,
    this.telefono,
    this.descuentoBp,
    this.notas,
    required this.activo,
    this.globalId,
    this.origenDispositivo,
    this.actualizadoEn,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['nombre'] = Variable<String>(nombre);
    if (!nullToAbsent || telefono != null) {
      map['telefono'] = Variable<String>(telefono);
    }
    if (!nullToAbsent || descuentoBp != null) {
      map['descuento_bp'] = Variable<int>(descuentoBp);
    }
    if (!nullToAbsent || notas != null) {
      map['notas'] = Variable<String>(notas);
    }
    map['activo'] = Variable<bool>(activo);
    if (!nullToAbsent || globalId != null) {
      map['global_id'] = Variable<String>(globalId);
    }
    if (!nullToAbsent || origenDispositivo != null) {
      map['origen_dispositivo'] = Variable<String>(origenDispositivo);
    }
    if (!nullToAbsent || actualizadoEn != null) {
      map['actualizado_en'] = Variable<DateTime>(actualizadoEn);
    }
    return map;
  }

  ClientesCompanion toCompanion(bool nullToAbsent) {
    return ClientesCompanion(
      id: Value(id),
      nombre: Value(nombre),
      telefono: telefono == null && nullToAbsent
          ? const Value.absent()
          : Value(telefono),
      descuentoBp: descuentoBp == null && nullToAbsent
          ? const Value.absent()
          : Value(descuentoBp),
      notas: notas == null && nullToAbsent
          ? const Value.absent()
          : Value(notas),
      activo: Value(activo),
      globalId: globalId == null && nullToAbsent
          ? const Value.absent()
          : Value(globalId),
      origenDispositivo: origenDispositivo == null && nullToAbsent
          ? const Value.absent()
          : Value(origenDispositivo),
      actualizadoEn: actualizadoEn == null && nullToAbsent
          ? const Value.absent()
          : Value(actualizadoEn),
    );
  }

  factory Cliente.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Cliente(
      id: serializer.fromJson<int>(json['id']),
      nombre: serializer.fromJson<String>(json['nombre']),
      telefono: serializer.fromJson<String?>(json['telefono']),
      descuentoBp: serializer.fromJson<int?>(json['descuentoBp']),
      notas: serializer.fromJson<String?>(json['notas']),
      activo: serializer.fromJson<bool>(json['activo']),
      globalId: serializer.fromJson<String?>(json['globalId']),
      origenDispositivo: serializer.fromJson<String?>(
        json['origenDispositivo'],
      ),
      actualizadoEn: serializer.fromJson<DateTime?>(json['actualizadoEn']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'nombre': serializer.toJson<String>(nombre),
      'telefono': serializer.toJson<String?>(telefono),
      'descuentoBp': serializer.toJson<int?>(descuentoBp),
      'notas': serializer.toJson<String?>(notas),
      'activo': serializer.toJson<bool>(activo),
      'globalId': serializer.toJson<String?>(globalId),
      'origenDispositivo': serializer.toJson<String?>(origenDispositivo),
      'actualizadoEn': serializer.toJson<DateTime?>(actualizadoEn),
