    return (StringBuffer('Cliente(')
          ..write('id: $id, ')
          ..write('nombre: $nombre, ')
          ..write('telefono: $telefono, ')
          ..write('descuentoBp: $descuentoBp, ')
          ..write('notas: $notas, ')
          ..write('activo: $activo, ')
          ..write('globalId: $globalId, ')
          ..write('origenDispositivo: $origenDispositivo, ')
          ..write('actualizadoEn: $actualizadoEn')
