class MedioDePago extends DataClass implements Insertable<MedioDePago> {
  final int id;
  final String nombre;

  /// De acá sale si una venta es efectivo/virtual/mixta (ComposicionPago del
  /// dominio): "Mixto" no es una fila acá, es una venta con dos pagos de
  /// distinta naturaleza (uno con esEfectivo=true y otro false).
  final bool esEfectivo;
  final int orden;
  final bool activo;

  /// Identidad de sincronización, migración v32→v33 (El dueño, 2026-09-19:
  /// "que se puedan modificar las reglas del negocio... desde el celular"
  /// — medios de pago entra junto con la Configuración completa de la
  /// companion). A diferencia de [Categorias.globalId], estas 2 filas se
  /// siembran igual en las dos plataformas desde siempre — ver
  /// `_globalIdMedioPagoEfectivo`/`_globalIdMedioPagoVirtual` en
  /// `database.dart`: el valor es FIJO, no generado al azar, para que
  /// escritorio y celular converjan al mismo id sin haber sincronizado
  /// todavía.
  final String? globalId;
  final String? origenDispositivo;
  final DateTime? actualizadoEn;
  const MedioDePago({
    required this.id,
    required this.nombre,
    required this.esEfectivo,
    required this.orden,
    required this.activo,
    this.globalId,
    this.origenDispositivo,
    this.actualizadoEn,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['nombre'] = Variable<String>(nombre);
    map['es_efectivo'] = Variable<bool>(esEfectivo);
    map['orden'] = Variable<int>(orden);
    map['activo'] = Variable<bool>(activo);
    if (!nullToAbsent || globalId != null) {
      map['global_id'] = Variable<String>(globalId);
    }
    if (!nullToAbsent || origenDispositivo != null) {
      map['origen_dispositivo'] = Variable<String>(origenDispositivo);
    }
    if (!nullToAbsent || actualizadoEn != null) {
      map['actualizado_en'] = Variable<DateTime>(actualizadoEn);
    }
    return map;
  }

  MediosDePagoCompanion toCompanion(bool nullToAbsent) {
    return MediosDePagoCompanion(
      id: Value(id),
      nombre: Value(nombre),
      esEfectivo: Value(esEfectivo),
      orden: Value(orden),
      activo: Value(activo),
      globalId: globalId == null && nullToAbsent
          ? const Value.absent()
          : Value(globalId),
      origenDispositivo: origenDispositivo == null && nullToAbsent
          ? const Value.absent()
          : Value(origenDispositivo),
      actualizadoEn: actualizadoEn == null && nullToAbsent
          ? const Value.absent()
          : Value(actualizadoEn),
    );
  }

