  MedioDePago copyWithCompanion(MediosDePagoCompanion data) {
    return MedioDePago(
      id: data.id.present ? data.id.value : this.id,
      nombre: data.nombre.present ? data.nombre.value : this.nombre,
      esEfectivo: data.esEfectivo.present
