    }
    map['es_varios'] = Variable<bool>(esVarios);
    map['tipo_cigarrillo'] = Variable<String>(tipoCigarrillo);
    map['es_pesable'] = Variable<bool>(esPesable);
    if (!nullToAbsent || precioCentavos != null) {
      map['precio_centavos'] = Variable<int>(precioCentavos);
    }
