    }
    map['stock'] = Variable<int>(stock);
    if (!nullToAbsent || stockGramos != null) {
      map['stock_gramos'] = Variable<int>(stockGramos);
    }
    map['stock_minimo'] = Variable<int>(stockMinimo);
    if (!nullToAbsent || stockMinimoGramos != null) {
      map['stock_minimo_gramos'] = Variable<int>(stockMinimoGramos);
    }
    map['precio_fijo'] = Variable<bool>(precioFijo);
    map['es_promo'] = Variable<bool>(esPromo);
    map['activo'] = Variable<bool>(activo);
    map['creado_en'] = Variable<DateTime>(creadoEn);
    map['actualizado_en'] = Variable<DateTime>(actualizadoEn);
    if (!nullToAbsent || globalId != null) {
      map['global_id'] = Variable<String>(globalId);
    }
    if (!nullToAbsent || origenDispositivo != null) {
      map['origen_dispositivo'] = Variable<String>(origenDispositivo);
    }
    if (!nullToAbsent || stockBaseSincronizacion != null) {
      map['stock_base_sincronizacion'] = Variable<int>(stockBaseSincronizacion);
    }
    if (!nullToAbsent || stockGramosBaseSincronizacion != null) {
      map['stock_gramos_base_sincronizacion'] = Variable<int>(
