      );
    }
    if (!nullToAbsent || stockBaseSincronizacionFecha != null) {
      map['stock_base_sincronizacion_fecha'] = Variable<DateTime>(
        stockBaseSincronizacionFecha,
      );
    }
    return map;
  }

