    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['nombre'] = Variable<String>(nombre);
    map['es_lata'] = Variable<bool>(esLata);
    return map;
  }

  CajasCompanion toCompanion(bool nullToAbsent) {
    return CajasCompanion(
      id: Value(id),
      nombre: Value(nombre),
      esLata: Value(esLata),
    );
  }

  factory Caja.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Caja(
      id: serializer.fromJson<int>(json['id']),
      nombre: serializer.fromJson<String>(json['nombre']),
      esLata: serializer.fromJson<bool>(json['esLata']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'nombre': serializer.toJson<String>(nombre),
      'esLata': serializer.toJson<bool>(esLata),
    };
  }

  Caja copyWith({int? id, String? nombre, bool? esLata}) => Caja(
    id: id ?? this.id,
    nombre: nombre ?? this.nombre,
    esLata: esLata ?? this.esLata,
  );
  Caja copyWithCompanion(CajasCompanion data) {
    return Caja(
      id: data.id.present ? data.id.value : this.id,
      nombre: data.nombre.present ? data.nombre.value : this.nombre,
      esLata: data.esLata.present ? data.esLata.value : this.esLata,
    );
  }

  @override
