class FilaVenta extends DataClass implements Insertable<FilaVenta> {
  final int id;
  final int sesionCajaId;
  final int? clienteId;
  final int usuarioId;
  final DateTime fecha;
  final int subtotalCentavos;

  /// Cliente Frecuente (Regla 17): 15% sobre el importe total. 0 para el resto.
  final int descuentoCentavos;
  final int recargoCigarrillosCentavos;
  final int redondeoCentavos;
  final int totalCentavos;
  final bool esFiado;

  /// Una venta cobrada se puede editar: al editarla, stock y caja se
  /// revierten y se vuelven a aplicar, y cada edición registra quién y
  /// cuándo (Regla 9).
  final int? editadaPorId;
  final DateTime? editadaEn;
  final String? motivoEdicion;

  /// Una venta cobrada se puede anular, pero solo mientras la sesión de
  /// caja de esa venta siga abierta (El dueño, 2026-09-13: eliminar una venta
  /// de un cierre ya arqueado descuadraría ese arqueo). A diferencia de
  /// editar, anular NUNCA borra `lineas_de_venta`/`pagos` ni reemplaza
  /// nada — revierte stock y caja (mismo mecanismo, `repositorio_edicion_venta.dart`)
  /// y marca estas tres columnas; la venta se sigue viendo en el historial,
  /// marcada como anulada (Regla 6, nunca se pierde el rastro).
  final int? anuladaPorId;
  final DateTime? anuladaEn;
  final String? motivoAnulacion;

  /// Identidad de sincronización (companion Android sin depender del
  /// escritorio) — ver el comentario de cabecera de la migración v29→v30 en
  /// `database.dart`. [actualizadoEn] se pisa en cada escritura (alta,
  /// edición o anulación) — a diferencia de [fecha] arriba (el momento de la
  /// venta en sí, que no cambia), esto es "cuándo se tocó por última vez
  /// esta fila", lo que el motor de sync necesita para saber qué mandar.
  final String? globalId;
  final String? origenDispositivo;
  final DateTime? actualizadoEn;

  /// Número de venta legible y único entre dispositivos (El dueño, 2026-10-03): `prefijo-correlativo`,
  /// ej. "K7-0123". El `id` local es distinto en la PC y en cada celular, así que no sirve para nombrar un ticket.
  /// Null en las ventas anteriores a la v48: ahí se sigue mostrando el `id`.
  final String? numero;
  const FilaVenta({
    required this.id,
    required this.sesionCajaId,
    this.clienteId,
    required this.usuarioId,
    required this.fecha,
    required this.subtotalCentavos,
    required this.descuentoCentavos,
    required this.recargoCigarrillosCentavos,
    required this.redondeoCentavos,
    required this.totalCentavos,
    required this.esFiado,
    this.editadaPorId,
    this.editadaEn,
    this.motivoEdicion,
    this.anuladaPorId,
    this.anuladaEn,
    this.motivoAnulacion,
    this.globalId,
    this.origenDispositivo,
    this.actualizadoEn,
    this.numero,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['sesion_caja_id'] = Variable<int>(sesionCajaId);
    if (!nullToAbsent || clienteId != null) {
      map['cliente_id'] = Variable<int>(clienteId);
    }
    map['usuario_id'] = Variable<int>(usuarioId);
    map['fecha'] = Variable<DateTime>(fecha);
    map['subtotal_centavos'] = Variable<int>(subtotalCentavos);
    map['descuento_centavos'] = Variable<int>(descuentoCentavos);
    map['recargo_cigarrillos_centavos'] = Variable<int>(
      recargoCigarrillosCentavos,
    );
    map['redondeo_centavos'] = Variable<int>(redondeoCentavos);
    map['total_centavos'] = Variable<int>(totalCentavos);
    map['es_fiado'] = Variable<bool>(esFiado);
    if (!nullToAbsent || editadaPorId != null) {
