  String toString() {
    return (StringBuffer('ArqueosIntermediosCompanion(')
          ..write('id: $id, ')
          ..write('sesionCajaId: $sesionCajaId, ')
          ..write('usuarioId: $usuarioId, ')
          ..write('fecha: $fecha, ')
          ..write('efectivoContadoCentavos: $efectivoContadoCentavos, ')
          ..write('efectivoEsperadoCentavos: $efectivoEsperadoCentavos, ')
          ..write('diferenciaCentavos: $diferenciaCentavos, ')
          ..write('mpContadoCentavos: $mpContadoCentavos, ')
          ..write('mpEsperadoCentavos: $mpEsperadoCentavos, ')
          ..write('mpDiferenciaCentavos: $mpDiferenciaCentavos, ')
          ..write('lataContadoCentavos: $lataContadoCentavos, ')
          ..write('lataEsperadoCentavos: $lataEsperadoCentavos, ')
          ..write('lataDiferenciaCentavos: $lataDiferenciaCentavos, ')
          ..write('globalId: $globalId, ')
          ..write('origenDispositivo: $origenDispositivo')
          ..write(')'))
        .toString();
  }
}

