class FilaLineaVenta extends DataClass implements Insertable<FilaLineaVenta> {
  final int id;
  final int ventaId;
  final int? productoId;

  /// Snapshot del nombre al momento de la venta: si el producto se borra o
  /// se renombra después, el ticket histórico no cambia.
  final String nombreProductoFoto;
  final int? proveedorIdFoto;
  final bool esVarios;

  /// 'ninguno' | 'atado' | 'suelto'.
  final String tipoCigarrillo;
  final bool esPesable;

  /// Unidades. Null si esPesable = true.
  final int? cantidad;

  /// Gramos. Null si esPesable = false (Regla 7).
  final int? gramos;

  /// Foto del precio (por unidad, o por kilo si esPesable) al momento de la
  /// venta (Regla 4: costo-foto).
  final int precioUnitarioCentavos;

  /// Foto del costo. Null cuando no había costo cargado (Regla 5/9):
  /// "Varios" y un producto de alta rápida pendiente son la misma situación
  /// de cara a la reposición (ver lib/domain/reposicion.dart) — nunca se
  /// guarda 0 en su lugar, porque un 0 haría que la reposición pareciera
  /// completa sin estarlo.
  final int? costoUnitarioCentavos;

  /// Identidad de sincronización — ver el comentario de [Ventas.globalId].
  /// Acá "editar la venta" es un delete+reinsert completo de estas filas
  /// (`repositorio_edicion_venta.dart::editarVenta`), así que un
  /// `actualizadoEn` puesto al insertar ya es "la última vez que se tocó
  /// esta fila" — no hace falta un UPDATE aparte.
  final String? globalId;
  final String? origenDispositivo;
  final DateTime? actualizadoEn;
  const FilaLineaVenta({
    required this.id,
    required this.ventaId,
    this.productoId,
    required this.nombreProductoFoto,
    this.proveedorIdFoto,
    required this.esVarios,
    required this.tipoCigarrillo,
    required this.esPesable,
    this.cantidad,
    this.gramos,
    required this.precioUnitarioCentavos,
    this.costoUnitarioCentavos,
    this.globalId,
    this.origenDispositivo,
    this.actualizadoEn,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['venta_id'] = Variable<int>(ventaId);
    if (!nullToAbsent || productoId != null) {
      map['producto_id'] = Variable<int>(productoId);
    }
    map['nombre_producto_foto'] = Variable<String>(nombreProductoFoto);
    if (!nullToAbsent || proveedorIdFoto != null) {
      map['proveedor_id_foto'] = Variable<int>(proveedorIdFoto);
    }
    map['es_varios'] = Variable<bool>(esVarios);
    map['tipo_cigarrillo'] = Variable<String>(tipoCigarrillo);
    map['es_pesable'] = Variable<bool>(esPesable);
    if (!nullToAbsent || cantidad != null) {
      map['cantidad'] = Variable<int>(cantidad);
    }
    if (!nullToAbsent || gramos != null) {
      map['gramos'] = Variable<int>(gramos);
    }
    map['precio_unitario_centavos'] = Variable<int>(precioUnitarioCentavos);
    if (!nullToAbsent || costoUnitarioCentavos != null) {
      map['costo_unitario_centavos'] = Variable<int>(costoUnitarioCentavos);
    }
    if (!nullToAbsent || globalId != null) {
      map['global_id'] = Variable<String>(globalId);
    }
    if (!nullToAbsent || origenDispositivo != null) {
