class Pago extends DataClass implements Insertable<Pago> {
  final int id;
  final int ventaId;
  final int medioPagoId;
  final int montoCentavos;

  /// 'qr' | 'debit_card' | 'credit_card' | null (Fase 12; crédito desde la etapa C). QR y Débito siguen siendo el
  /// mismo `medioPagoId` de siempre ("Mercado Pago") — este es solo el
  /// dato de qué canal de la terminal Point se usó, o null si el pago no
  /// pasó por ahí (efectivo, o Mercado Pago cobrado a mano como hasta
  /// ahora). Ninguna consulta de arqueo/planilla/historial lee esta
  /// columna: todas agrupan por `medioPagoId`, así que agregarla no las
  /// afecta (confirmado archivo por archivo antes de escribir esto).
  final String? canal;

  /// Identidad de sincronización — mismo criterio que
  /// [LineasDeVenta.globalId]: un delete+reinsert al editar la venta ya deja
  /// el `actualizadoEn` del insert como la última vez que se tocó la fila.
  final String? globalId;
  final String? origenDispositivo;
  final DateTime? actualizadoEn;
  const Pago({
    required this.id,
    required this.ventaId,
    required this.medioPagoId,
    required this.montoCentavos,
    this.canal,
    this.globalId,
    this.origenDispositivo,
    this.actualizadoEn,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['venta_id'] = Variable<int>(ventaId);
    map['medio_pago_id'] = Variable<int>(medioPagoId);
    map['monto_centavos'] = Variable<int>(montoCentavos);
    if (!nullToAbsent || canal != null) {
      map['canal'] = Variable<String>(canal);
    }
    if (!nullToAbsent || globalId != null) {
      map['global_id'] = Variable<String>(globalId);
    }
    if (!nullToAbsent || origenDispositivo != null) {
      map['origen_dispositivo'] = Variable<String>(origenDispositivo);
    }
    if (!nullToAbsent || actualizadoEn != null) {
      map['actualizado_en'] = Variable<DateTime>(actualizadoEn);
    }
    return map;
  }

  PagosCompanion toCompanion(bool nullToAbsent) {
    return PagosCompanion(
      id: Value(id),
      ventaId: Value(ventaId),
      medioPagoId: Value(medioPagoId),
      montoCentavos: Value(montoCentavos),
      canal: canal == null && nullToAbsent
          ? const Value.absent()
          : Value(canal),
      globalId: globalId == null && nullToAbsent
          ? const Value.absent()
          : Value(globalId),
      origenDispositivo: origenDispositivo == null && nullToAbsent
          ? const Value.absent()
          : Value(origenDispositivo),
      actualizadoEn: actualizadoEn == null && nullToAbsent
          ? const Value.absent()
          : Value(actualizadoEn),
    );
  }

  factory Pago.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Pago(
      id: serializer.fromJson<int>(json['id']),
      ventaId: serializer.fromJson<int>(json['ventaId']),
      medioPagoId: serializer.fromJson<int>(json['medioPagoId']),
      montoCentavos: serializer.fromJson<int>(json['montoCentavos']),
      canal: serializer.fromJson<String?>(json['canal']),
      globalId: serializer.fromJson<String?>(json['globalId']),
      origenDispositivo: serializer.fromJson<String?>(
        json['origenDispositivo'],
      ),
      actualizadoEn: serializer.fromJson<DateTime?>(json['actualizadoEn']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'ventaId': serializer.toJson<int>(ventaId),
      'medioPagoId': serializer.toJson<int>(medioPagoId),
      'montoCentavos': serializer.toJson<int>(montoCentavos),
      'canal': serializer.toJson<String?>(canal),
      'globalId': serializer.toJson<String?>(globalId),
      'origenDispositivo': serializer.toJson<String?>(origenDispositivo),
      'actualizadoEn': serializer.toJson<DateTime?>(actualizadoEn),
    };
  }

  Pago copyWith({
    int? id,
    int? ventaId,
    int? medioPagoId,
    int? montoCentavos,
    Value<String?> canal = const Value.absent(),
    Value<String?> globalId = const Value.absent(),
    Value<String?> origenDispositivo = const Value.absent(),
    Value<DateTime?> actualizadoEn = const Value.absent(),
  }) => Pago(
    id: id ?? this.id,
    ventaId: ventaId ?? this.ventaId,
    medioPagoId: medioPagoId ?? this.medioPagoId,
    montoCentavos: montoCentavos ?? this.montoCentavos,
    canal: canal.present ? canal.value : this.canal,
    globalId: globalId.present ? globalId.value : this.globalId,
    origenDispositivo: origenDispositivo.present
        ? origenDispositivo.value
        : this.origenDispositivo,
    actualizadoEn: actualizadoEn.present
        ? actualizadoEn.value
        : this.actualizadoEn,
  );
  Pago copyWithCompanion(PagosCompanion data) {
    return Pago(
