class Pendiente extends DataClass implements Insertable<Pendiente> {
  final int id;

  /// 'FIADO' | 'ENCARGUE'.
  final String tipo;

  /// Cliente Frecuente es cliente formal porque tiene descuento configurado (Regla
  /// 17) y hace falta linkearlo. Un fiado ocasional es solo un nombre
  /// escrito: Regla 15 dice explícitamente "sin cuenta corriente formal",
  /// así que no todo fiado obliga a crear una fila en `clientes`.
  final int? clienteId;
  final String? nombreLibre;

  /// Fiado: cuánto queda anotado.
  final int? montoCentavos;

  /// Encargue: qué se pidió.
  final String? descripcion;

  /// Encargue por apartado (El dueño, 2026-10-02): lo que se apartó, como JSON
  /// `[{"gid": <global_id del producto>, "nombre": ..., "cantidad"|"gramos": ...}]`. Va por `global_id` y no por `id`
  /// porque el encargue se sincroniza y el id local de un producto no vale en otro dispositivo. Null en un encargue
  /// viejo de texto libre (`descripcion`).
  final String? lineasJson;

  /// 'PENDIENTE' | 'RESUELTO' | 'CANCELADO' (un encargue cancelado devolvió lo apartado al stock).
  final String estado;

  /// Cuando un fiado se cobra, entra como venta de ese día (Regla 15): acá
  /// queda la venta que lo saldó.
  final int? ventaId;

  /// Seña de un encargue (schemaVersion 55, rediseño v4, 2026-10-06; ver `domain/sena.dart` y `docs/PLAN-SENA.md`): lo que el cliente
  /// dejó adelantado. Entró a la caja como INGRESO en el momento (cajón si [senaEsEfectivo], Mercado Pago si no) y NO es una venta.
  /// 0 = sin seña. Al cancelar vuelve por la misma caja; al entregar se aplica como pago de la venta del día de la entrega.
  final int senaCentavos;
  final bool senaEsEfectivo;
  final DateTime fechaCreacion;
  final DateTime? fechaResuelta;
  final int usuarioId;

  /// Identidad de sincronización — ver el comentario de cabecera de la
  /// migración v29→v30 en `database.dart`. [actualizadoEn] se pisa al
  /// resolver (`estado` pasa de PENDIENTE a RESUELTO), no solo al crear.
  final String? globalId;
  final String? origenDispositivo;
  final DateTime? actualizadoEn;
  const Pendiente({
    required this.id,
    required this.tipo,
    this.clienteId,
    this.nombreLibre,
    this.montoCentavos,
    this.descripcion,
    this.lineasJson,
    required this.estado,
    this.ventaId,
    required this.senaCentavos,
    required this.senaEsEfectivo,
    required this.fechaCreacion,
    this.fechaResuelta,
    required this.usuarioId,
    this.globalId,
    this.origenDispositivo,
    this.actualizadoEn,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['tipo'] = Variable<String>(tipo);
    if (!nullToAbsent || clienteId != null) {
      map['cliente_id'] = Variable<int>(clienteId);
    }
    if (!nullToAbsent || nombreLibre != null) {
      map['nombre_libre'] = Variable<String>(nombreLibre);
    }
    if (!nullToAbsent || montoCentavos != null) {
      map['monto_centavos'] = Variable<int>(montoCentavos);
    }
    if (!nullToAbsent || descripcion != null) {
      map['descripcion'] = Variable<String>(descripcion);
    }
    if (!nullToAbsent || lineasJson != null) {
      map['lineas_json'] = Variable<String>(lineasJson);
    }
    map['estado'] = Variable<String>(estado);
    if (!nullToAbsent || ventaId != null) {
      map['venta_id'] = Variable<int>(ventaId);
    }
    map['sena_centavos'] = Variable<int>(senaCentavos);
    map['sena_es_efectivo'] = Variable<bool>(senaEsEfectivo);
    map['fecha_creacion'] = Variable<DateTime>(fechaCreacion);
    if (!nullToAbsent || fechaResuelta != null) {
      map['fecha_resuelta'] = Variable<DateTime>(fechaResuelta);
    }
    map['usuario_id'] = Variable<int>(usuarioId);
    if (!nullToAbsent || globalId != null) {
      map['global_id'] = Variable<String>(globalId);
    }
    if (!nullToAbsent || origenDispositivo != null) {
      map['origen_dispositivo'] = Variable<String>(origenDispositivo);
    }
    if (!nullToAbsent || actualizadoEn != null) {
      map['actualizado_en'] = Variable<DateTime>(actualizadoEn);
    }
    return map;
  }

