class AccesoDirecto extends DataClass implements Insertable<AccesoDirecto> {
  final int id;

  /// 0..5. Define el orden de la grilla, no cambia con la configuración.
  final int posicion;

  /// La letra o dígito de "Alt+" seguido de esta tecla. Null = posición sin
  /// asignar todavía.
  /// Única entre las posiciones asignadas: dos slots con la misma tecla
  /// serían un atajo ambiguo.
  final String? tecla;
  final int? productoId;
  const AccesoDirecto({
    required this.id,
    required this.posicion,
    this.tecla,
    this.productoId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['posicion'] = Variable<int>(posicion);
    if (!nullToAbsent || tecla != null) {
      map['tecla'] = Variable<String>(tecla);
    }
    if (!nullToAbsent || productoId != null) {
      map['producto_id'] = Variable<int>(productoId);
    }
    return map;
  }

  AccesosDirectosCompanion toCompanion(bool nullToAbsent) {
    return AccesosDirectosCompanion(
      id: Value(id),
      posicion: Value(posicion),
      tecla: tecla == null && nullToAbsent
          ? const Value.absent()
          : Value(tecla),
      productoId: productoId == null && nullToAbsent
          ? const Value.absent()
          : Value(productoId),
    );
  }

  factory AccesoDirecto.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return AccesoDirecto(
      id: serializer.fromJson<int>(json['id']),
      posicion: serializer.fromJson<int>(json['posicion']),
      tecla: serializer.fromJson<String?>(json['tecla']),
      productoId: serializer.fromJson<int?>(json['productoId']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'posicion': serializer.toJson<int>(posicion),
      'tecla': serializer.toJson<String?>(tecla),
      'productoId': serializer.toJson<int?>(productoId),
    };
  }

  AccesoDirecto copyWith({
    int? id,
    int? posicion,
    Value<String?> tecla = const Value.absent(),
    Value<int?> productoId = const Value.absent(),
  }) => AccesoDirecto(
    id: id ?? this.id,
    posicion: posicion ?? this.posicion,
    tecla: tecla.present ? tecla.value : this.tecla,
    productoId: productoId.present ? productoId.value : this.productoId,
  );
  AccesoDirecto copyWithCompanion(AccesosDirectosCompanion data) {
    return AccesoDirecto(
      id: data.id.present ? data.id.value : this.id,
      posicion: data.posicion.present ? data.posicion.value : this.posicion,
      tecla: data.tecla.present ? data.tecla.value : this.tecla,
      productoId: data.productoId.present
          ? data.productoId.value
          : this.productoId,
    );
  }

  @override
  String toString() {
    return (StringBuffer('AccesoDirecto(')
          ..write('id: $id, ')
          ..write('posicion: $posicion, ')
          ..write('tecla: $tecla, ')
          ..write('productoId: $productoId')
          ..write(')'))
        .toString();
  }

