class ConfiguracionNegocio extends DataClass
    implements Insertable<ConfiguracionNegocio> {
  final int id;

  /// Regla 6 — mismos tres montos y mismo default que tenían en
  /// `ConfiguracionTabla`.
  final int recargoPrimerAtadoCentavos;
  final int recargoAtadoAdicionalCentavos;
  final int recargoSueltoCentavos;

  /// Regla 2, paso de redondeo del total en efectivo. Default 100 pesos.
  final int pasoRedondeoCentavos;

  /// Producto del botón fijo de "vuelto" (Alt+C en la venta). A diferencia
  /// de la columna vieja en `ConfiguracionTabla` (sin referencia declarada,
  /// un descuido de la fase 8), esta sí la declara — `productos` ya
  /// sincroniza, así que esta FK necesita la misma traducción por
  /// `global_id` que ya usan `productos.categoria_id`/`proveedor_id`
  /// (`_referenciasCruzadas`, `repositorio_sincronizacion.dart`).
  final int? productoVueltoId;

  /// Generalización del producto (fase 1): datos propios de cada comercio.
  /// Las tres columnas nacen vacías — nada las lee todavía con efecto; las
  /// fases siguientes las usan (marca visible, ticket, módulos). Vacío
  /// significa "sin configurar", no "sin nombre a propósito".
  ///
  /// Nombre del comercio: lo que se ve en la ventana, el ticket y el celular.
  final String nombreComercio;

  /// Encabezado del ticket, una línea por renglón (nombre, dirección…).
  final String encabezadoTicket;

  /// Módulos apagados, claves separadas por coma (`domain/modulos.dart`).
  /// Vacío = todos activos, que es como funciona la app hoy. Se guardan los
  /// apagados para que un módulo nuevo nazca activo sin migración.
  final String modulosDesactivados;

  /// Identidad de sincronización — ver el comentario de
  /// `Categorias.globalId` (`tables/catalogo.dart`) para el porqué completo.
  final String? globalId;
  final String? origenDispositivo;
  final DateTime? actualizadoEn;
  const ConfiguracionNegocio({
    required this.id,
    required this.recargoPrimerAtadoCentavos,
    required this.recargoAtadoAdicionalCentavos,
    required this.recargoSueltoCentavos,
    required this.pasoRedondeoCentavos,
    this.productoVueltoId,
    required this.nombreComercio,
    required this.encabezadoTicket,
    required this.modulosDesactivados,
    this.globalId,
    this.origenDispositivo,
    this.actualizadoEn,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['recargo_primer_atado_centavos'] = Variable<int>(
      recargoPrimerAtadoCentavos,
    );
    map['recargo_atado_adicional_centavos'] = Variable<int>(
      recargoAtadoAdicionalCentavos,
    );
    map['recargo_suelto_centavos'] = Variable<int>(recargoSueltoCentavos);
    map['paso_redondeo_centavos'] = Variable<int>(pasoRedondeoCentavos);
    if (!nullToAbsent || productoVueltoId != null) {
      map['producto_vuelto_id'] = Variable<int>(productoVueltoId);
    }
    map['nombre_comercio'] = Variable<String>(nombreComercio);
    map['encabezado_ticket'] = Variable<String>(encabezadoTicket);
    map['modulos_desactivados'] = Variable<String>(modulosDesactivados);
    if (!nullToAbsent || globalId != null) {
      map['global_id'] = Variable<String>(globalId);
    }
    if (!nullToAbsent || origenDispositivo != null) {
      map['origen_dispositivo'] = Variable<String>(origenDispositivo);
    }
    if (!nullToAbsent || actualizadoEn != null) {
      map['actualizado_en'] = Variable<DateTime>(actualizadoEn);
    }
    return map;
  }

  ConfiguracionNegocioTablaCompanion toCompanion(bool nullToAbsent) {
    return ConfiguracionNegocioTablaCompanion(
      id: Value(id),
      recargoPrimerAtadoCentavos: Value(recargoPrimerAtadoCentavos),
      recargoAtadoAdicionalCentavos: Value(recargoAtadoAdicionalCentavos),
      recargoSueltoCentavos: Value(recargoSueltoCentavos),
      pasoRedondeoCentavos: Value(pasoRedondeoCentavos),
      productoVueltoId: productoVueltoId == null && nullToAbsent
          ? const Value.absent()
          : Value(productoVueltoId),
      nombreComercio: Value(nombreComercio),
      encabezadoTicket: Value(encabezadoTicket),
      modulosDesactivados: Value(modulosDesactivados),
      globalId: globalId == null && nullToAbsent
          ? const Value.absent()
          : Value(globalId),
      origenDispositivo: origenDispositivo == null && nullToAbsent
          ? const Value.absent()
          : Value(origenDispositivo),
      actualizadoEn: actualizadoEn == null && nullToAbsent
          ? const Value.absent()
          : Value(actualizadoEn),
    );
  }

  factory ConfiguracionNegocio.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
