class MovimientoDeuda extends DataClass implements Insertable<MovimientoDeuda> {
  final int id;
  final int proveedorId;

  /// 'CARGO' (le debo más) | 'PAGO' (le pagué).
  final String tipo;
  final int montoCentavos;

  /// De cuándo es la deuda (cargo) o cuándo se pagó (pago). Lo elige quien
  /// carga: la mercadería puede haber llegado antes de anotarla.
  final DateTime fecha;

  /// Remito, factura o lo que ayude a reconocerla.
  final String? nota;
  final int usuarioId;

  /// 'cajon' | 'mp' | 'lata' | 'fuera' — solo en pagos. 'fuera' es plata
  /// que no pasó por ninguna caja de la app (transferencia desde otra cuenta).
  final String? origenPago;

  /// El movimiento de caja que generó este pago (null si salió 'fuera').
  final int? movimientoCajaId;

  /// Anulado = deja de contar en el saldo, pero la fila queda (Regla 6:
  /// todo deja rastro).
  final DateTime? anuladoEn;
  final DateTime creadoEn;
  const MovimientoDeuda({
    required this.id,
    required this.proveedorId,
    required this.tipo,
    required this.montoCentavos,
    required this.fecha,
    this.nota,
    required this.usuarioId,
    this.origenPago,
    this.movimientoCajaId,
    this.anuladoEn,
    required this.creadoEn,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['proveedor_id'] = Variable<int>(proveedorId);
    map['tipo'] = Variable<String>(tipo);
    map['monto_centavos'] = Variable<int>(montoCentavos);
    map['fecha'] = Variable<DateTime>(fecha);
    if (!nullToAbsent || nota != null) {
      map['nota'] = Variable<String>(nota);
    }
    map['usuario_id'] = Variable<int>(usuarioId);
    if (!nullToAbsent || origenPago != null) {
      map['origen_pago'] = Variable<String>(origenPago);
    }
    if (!nullToAbsent || movimientoCajaId != null) {
      map['movimiento_caja_id'] = Variable<int>(movimientoCajaId);
    }
    if (!nullToAbsent || anuladoEn != null) {
      map['anulado_en'] = Variable<DateTime>(anuladoEn);
    }
    map['creado_en'] = Variable<DateTime>(creadoEn);
    return map;
  }

  MovimientosDeudaCompanion toCompanion(bool nullToAbsent) {
    return MovimientosDeudaCompanion(
      id: Value(id),
      proveedorId: Value(proveedorId),
