      fecha: Value(fecha),
      nota: nota == null && nullToAbsent ? const Value.absent() : Value(nota),
      usuarioId: Value(usuarioId),
      origenPago: origenPago == null && nullToAbsent
          ? const Value.absent()
          : Value(origenPago),
      movimientoCajaId: movimientoCajaId == null && nullToAbsent
          ? const Value.absent()
          : Value(movimientoCajaId),
      anuladoEn: anuladoEn == null && nullToAbsent
          ? const Value.absent()
          : Value(anuladoEn),
      creadoEn: Value(creadoEn),
    );
  }

